void restart_scsi_dma(void *opaque) {
    SCSIDiskState *s = opaque;
    SCSIRequest *req;

    if (s->bh) {
        qemu_bh_delete(s->bh);
        s->bh = NULL;
    }

    QTAILQ_FOREACH(req, &s->requests, next) {
        if (req->retry) {
            req->retry = false;

            switch (req->type) {
                case SCSI_REQ_READ:
                    // Process read operation
                    if (scsi_disk_read_req(req)) {
                        scsi_req_complete(req, 0);
                    }
                    break;
                case SCSI_REQ_WRITE:
                    // Process write operation
                    if (scsi_disk_write_req(req)) {
                        scsi_req_complete(req, 0);
                    }
                    break;
                case SCSI_REQ_FLUSH:
                    // Emulate flush operation
                    scsi_req_complete(req, 0);
                    break;
                default:
                    break;
            }
        }
    }
}

void restart_scsi_dma(void *opaque) {
    SCSIDiskState *s = (SCSIDiskState *)opaque;

    if (s->bh) {
        qemu_bh_delete(s->bh);
        s->bh = NULL;
    }

    SCSIRequest *req;
    QLIST_FOREACH(req, &s->requests, next) {
        if (req->status == SCSI_REQ_STATUS_RETRY) {
            req->status = SCSI_REQ_STATUS_OK;
            switch (req->retry_type) {
                case SCSI_RETRY_READ:
                    // Perform read operation
                    break;
                case SCSI_RETRY_WRITE:
                    // Perform write operation
                    break;
                case SCSI_RETRY_FLUSH:
                    // Emulate flush command
                    break;
                default:
                    break;
            }
            if (req->status == SCSI_REQ_STATUS_OK) {
                scsi_req_complete(req, 0);
            }
        }
    }
}

void restart_scsi_dma(void *opaque) {
    SCSIDiskState *s = opaque;
    SCSIRequest *req;

    qemu_bh_delete(s->bh);
    s->bh = NULL;

    QTAILQ_FOREACH(req, &s->requests, next) {
        if (req->retry) {
            req->retry = false;
            switch (req->type) {
                case SCSI_REQ_READ:
                    scsi_read_data(s, req);
                    break;
                case SCSI_REQ_WRITE:
                    scsi_write_data(s, req);
                    break;
                case SCSI_REQ_FLUSH:
                    scsi_emulate_command(s, req);
                    break;
                default:
                    break;
            }
            if (req->status == SCSI_STATUS_OK) {
                scsi_req_complete(req, req->status);
            }
        }
    }
}

